import{_ as o,o as t,c as n,aJ as r}from"./chunks/framework.axd7qhV-.js";const g=JSON.parse('{"title":"Bidding-zone GeoJSON — attribution","description":"","frontmatter":{},"headers":[],"relativePath":"assets/bidding_zones/ATTRIBUTION.md","filePath":"assets/bidding_zones/ATTRIBUTION.md","lastUpdated":null}'),a={name:"assets/bidding_zones/ATTRIBUTION.md"};function s(i,e,d,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="Bidding-zone-GeoJSON-—-attribution" tabindex="-1">Bidding-zone GeoJSON — attribution <a class="header-anchor" href="#Bidding-zone-GeoJSON-—-attribution" aria-label="Permalink to &quot;Bidding-zone GeoJSON — attribution {#Bidding-zone-GeoJSON-—-attribution}&quot;">​</a></h1><p>The <code>*.geojson</code> files in this directory are <strong>not</strong> original to ENTSOE.jl. They are vendored, unmodified, from the <strong><code>entsoe-py</code></strong> project:</p><ul><li><p>Source: <a href="https://github.com/EnergieID/entsoe-py/tree/master/entsoe/geo/geojson" target="_blank" rel="noreferrer">https://github.com/EnergieID/entsoe-py/tree/master/entsoe/geo/geojson</a></p></li><li><p>Author: <strong>EnergieID cvba-so</strong> and the <code>entsoe-py</code> contributors</p></li><li><p>License: <strong>MIT</strong> (© 2017 EnergieID cvba-so) — the same permissive licence as ENTSOE.jl, so redistribution here is fine as long as this credit is kept.</p></li></ul><p>We use them only as documentation assets to draw the bidding-zone map in the cross-border flows tutorial (<code>docs/src/tutorial_flow_map.md</code>); they are not part of the importable Julia package.</p><h2 id="Provenance-of-the-shapes-per-entsoe-py&#39;s-own-README" tabindex="-1">Provenance of the shapes (per <code>entsoe-py</code>&#39;s own README) <a class="header-anchor" href="#Provenance-of-the-shapes-per-entsoe-py&#39;s-own-README" aria-label="Permalink to &quot;Provenance of the shapes (per `entsoe-py`&#39;s own README) {#Provenance-of-the-shapes-per-entsoe-py&#39;s-own-README}&quot;">​</a></h2><ul><li><p><strong>Single-zone countries:</strong> <a href="https://www.naturalearthdata.com/downloads/10m-cultural-vectors/" target="_blank" rel="noreferrer">Natural Earth</a> 10 m Admin-0 cultural vectors.</p></li><li><p><strong>Norway (NO_1…NO_5):</strong> <a href="https://temakart.nve.no/link/?link=vannkraft" target="_blank" rel="noreferrer">NVE Temakart</a>.</p></li><li><p><strong>Sweden (SE_1…SE_4):</strong> based on <a href="https://www.natomraden.se/" target="_blank" rel="noreferrer">https://www.natomraden.se/</a> (manually redrawn).</p></li><li><p><strong>Italy (IT_*):</strong> regions aggregated per the GME (Gestore dei Mercati Energetici) market-zone definition, as documented in <code>entsoe-py</code>&#39;s README.</p></li></ul><p>Rings were rewound to RFC 7946 winding order with <code>geojson-rewind</code>.</p><h2 id="File-naming" tabindex="-1">File naming <a class="header-anchor" href="#File-naming" aria-label="Permalink to &quot;File naming {#File-naming}&quot;">​</a></h2><p>Each file is one <code>FeatureCollection</code> with a single feature carrying a <code>zoneName</code> property (e.g. <code>NL</code>, <code>DE_LU</code>, <code>NO_2</code>). The <code>_2020</code>-suffixed Italian files (<code>IT_CNOR_2020</code>, <code>IT_CSUD_2020</code>, <code>IT_SUD_2020</code>) are the pre-2021 zone boundaries; <code>entsoe-py</code>&#39;s <code>load_zones</code> selects them for dates before 2021-01-01. <code>IT_CALA</code> (Calabria) only exists from 2021 onward.</p><p>To refresh these files, re-download from the source URL above — they are vendored verbatim, so a plain copy is all that is needed.</p>',10)])])}const u=o(a,[["render",s]]);export{g as __pageData,u as default};
